<?php
$virusScans=$service->virusScans();$virusFindings=$service->virusFindings();$virusSchedules=array();
if($workerService)foreach($workerService->tasks() as $task)if($task['worker_id']==='security_center.scheduled_virus_scan')$virusSchedules[]=$task;
?>
<header class="sec-subhero"><div><span>PHP-MALWARE-ERKENNUNG</span><h3>Virenscanner</h3><p>Lokale Prüfung auf Webshells, getarnte Programme, verschleierte Nutzlasten und manipulierte Archive – ohne externe Dienste oder Systembefehle.</p></div><span class="sec-badge <?php echo ($settings['virus_scanner_enabled']??'1')==='1'?'success':'warning';?>"><?php echo ($settings['virus_scanner_enabled']??'1')==='1'?'Aktiv':'Deaktiviert';?></span></header>

<form method="post"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="settings"><input type="hidden" name="setting_scope" value="virus"><?php echo $admin->getFTAN();?><section><h3>Virenscanner-Einstellungen</h3><div class="sec-options"><?php sec_switch($settings,'virus_scanner_enabled','Virenscanner aktivieren','Alle Prüfungen werden ausschließlich portionsweise über den Worker ausgeführt.');sec_switch($settings,'virus_scan_archives','ZIP-Inhalte prüfen','Archive werden mit festen Grenzen für Anzahl und entpackte Größe untersucht.');?></div><div class="sec-form-grid"><label>Dateien je Worker-Lauf<input type="number" name="virus_files_per_run" min="5" max="300" value="<?php echo (int)($settings['virus_files_per_run']??80);?>"></label><label>Maximale Dateigröße<input type="number" name="virus_max_file_mb" min="1" max="64" value="<?php echo (int)($settings['virus_max_file_mb']??16);?>"><small>MB je Datei</small></label></div><button>Virenscanner-Einstellungen speichern</button></section></form>

<section><div class="sec-section-head"><div><h3>Einmalige Virenscans</h3><p class="sec-muted">Der Auftrag wird nur vorgemerkt; der Worker verarbeitet ihn in begrenzten Portionen.</p></div><form method="post"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_scan"><?php echo $admin->getFTAN();?><button>Neuen Virenscan einplanen</button></form></div><div class="sec-scroll"><table><thead><tr><th>Scan</th><th>Status</th><th>Dateien</th><th>Funde</th><th>Beginn</th><th></th></tr></thead><tbody><?php foreach($virusScans as $scan){?><tr><td><code><?php echo sec_h($scan['scan_id']);?></code></td><td><span class="sec-badge <?php echo $scan['status']==='done'?'success':($scan['status']==='failed'?'critical':'warning');?>"><?php echo sec_h($scan['status']);?></span><?php if(!empty($scan['last_error'])){?><small><?php echo sec_h($scan['last_error']);?></small><?php }?></td><td><?php echo (int)$scan['files_scanned'];?></td><td><?php echo (int)$scan['findings_count'];?></td><td><?php echo sec_h(sec_time($scan['started_at']?:$scan['created_at']));?></td><td><?php if($scan['status']==='queued'){?><form method="post" data-confirm="Soll dieser geplante Virenscan gelöscht werden?"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_scan_delete"><input type="hidden" name="id" value="<?php echo (int)$scan['id'];?>"><?php echo $admin->getFTAN();?><button class="sec-danger">Löschen</button></form><?php }?></td></tr><?php }?><?php if(!$virusScans){?><tr><td colspan="6" class="sec-muted">Noch kein Virenscan eingeplant.</td></tr><?php }?></tbody></table></div></section>

<section><h3>Regelmäßige und terminierte Virenscans</h3><?php if(!$workerService){?><p>Für Virenscan-Zeitpläne muss der Worker installiert sein.</p><?php }else{?><form method="post" class="sec-schedule-form"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_schedule_save"><?php echo $admin->getFTAN();?><label>Name<input name="name" value="Regelmäßiger Virenscan"></label><div class="sec-choice"><label><input type="radio" name="schedule_mode" value="rate" checked> X-mal pro Zeitraum</label><label><input type="radio" name="schedule_mode" value="calendar"> Fester Kalendertermin</label></div><div class="sec-schedule-grid" data-schedule-mode="rate"><label>Anzahl<input type="number" name="schedule_count" min="1" max="12" value="1"></label><label>Zeitraum<select name="schedule_period"><option value="hour">Stunde</option><option value="day" selected>Tag</option><option value="week">Woche</option><option value="month">Monat</option><option value="year">Jahr</option></select></label><label>Startzeit<input type="time" name="schedule_time" value="04:00"></label></div><div class="sec-schedule-grid" data-schedule-mode="calendar" hidden><label>Rhythmus<select name="calendar_period" disabled><option value="once">Einmalig</option><option value="hour">Stündlich</option><option value="day">Täglich</option><option value="week">Wöchentlich</option><option value="month">Monatlich</option><option value="year">Jährlich</option></select></label><label data-once>Zeitpunkt<input type="datetime-local" name="run_at" disabled></label><label data-calendar-time>Uhrzeit<input type="time" name="schedule_time" value="04:00" disabled></label><label data-weekday>Wochentag<select name="schedule_weekday" disabled><option value="1">Montag</option><option value="2">Dienstag</option><option value="3">Mittwoch</option><option value="4">Donnerstag</option><option value="5">Freitag</option><option value="6">Samstag</option><option value="0">Sonntag</option></select></label><label data-monthday>Tag<input type="number" name="schedule_monthday" min="1" max="28" value="1" disabled></label><label data-month>Monat<select name="schedule_month" disabled><?php foreach(array('Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember') as $i=>$month)echo '<option value="'.($i+1).'">'.$month.'</option>';?></select></label></div><button>Zeitplan hinzufügen</button></form><div class="sec-scroll"><table><thead><tr><th>Name</th><th>Cron-Schema</th><th>Nächster Lauf</th><th>Status</th><th>Aktiv</th><th></th></tr></thead><tbody><?php foreach($virusSchedules as $schedule){?><tr><td><?php echo sec_h($schedule['name']);?></td><td><code><?php echo sec_h($schedule['cron_expression']);?></code></td><td><?php echo sec_h($schedule['next_run_display']?:'–');?></td><td><?php echo sec_h($schedule['last_status']?:'Bereit');?></td><td><form method="post"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_schedule_toggle"><input type="hidden" name="schedule_id" value="<?php echo (int)$schedule['id'];?>"><input type="hidden" name="active" value="<?php echo $schedule['active']?'0':'1';?>"><?php echo $admin->getFTAN();?><label class="sec-slider"><input type="checkbox"<?php echo $schedule['active']?' checked':'';?> data-auto-submit><i></i></label></form></td><td><form method="post" data-confirm="Soll dieser Virenscan-Zeitplan gelöscht werden?"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_schedule_delete"><input type="hidden" name="schedule_id" value="<?php echo (int)$schedule['id'];?>"><?php echo $admin->getFTAN();?><button class="sec-danger">Löschen</button></form></td></tr><?php }?></tbody></table></div><?php }?></section>

<section><h3>Offene Virenscanner-Funde</h3><div class="sec-scroll"><table><thead><tr><th>Priorität</th><th>Datei</th><th>Erkennung</th><th>Aktion</th></tr></thead><tbody><?php foreach($virusFindings as $finding){?><tr><td><span class="sec-badge <?php echo sec_h($finding['severity']);?>"><?php echo sec_h($finding['severity']);?></span></td><td><strong><?php echo sec_h($finding['file_path']);?></strong><br><small><?php echo sec_h($finding['message']);?></small></td><td><code><?php echo sec_h($finding['rule_id']);?></code></td><td><form method="post"><input type="hidden" name="sc_page" value="virus_scanner"><input type="hidden" name="action" value="virus_finding"><input type="hidden" name="id" value="<?php echo (int)$finding['id'];?>"><?php echo $admin->getFTAN();?><button name="status" value="resolved">Erledigt</button><button name="status" value="ignored">Ignorieren</button></form></td></tr><?php }?><?php if(!$virusFindings){?><tr><td colspan="4" class="sec-muted">Keine offenen Virenscanner-Funde.</td></tr><?php }?></tbody></table></div></section>
